with base as (select id, order_id, shipped_date, delivered_date, cost, coalesce(cost, 0) as cost_filled, case when carrier = 'Flash' then 1 else 0 end as is_flash, coalesce(carrier, 'NONE') as carrier_filled from shipments where order_id is not null and shipped_date > date '2023-05-28') select id, order_id, delivered_date, cost, carrier_filled from (select *, rank() over (partition by order_id order by delivered_date asc) as rank_in_group from base) x where rank_in_group = 1;
